INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3509970, 491495, 15711, '<td valign="top">HEE HEE - great retro feel ( although visors were not worn in the 50''s).  hee hee  Love the swimsuit and her pose.  The striped beach bag is wonderful too. 8</td>', 'HEE HEE - great retro feel ( although visors were not worn in the 50''s).  hee hee  Love the swimsuit and her pose.  The striped beach bag is wonderful too. 8', '2007-04-02 12:39:42.000000', NULL, 1),
(3509973, 491402, 15711, '<td valign="top">Oh that''s great with the earpiece. tee hee</td>', 'Oh that''s great with the earpiece. tee hee', '2007-04-02 12:40:18.000000', NULL, 1),
(3509977, 491310, 69102, '<td valign="top">This is a very nice picture, but it really doesn''t fit my understanding of the term anachronism.</td>', 'This is a very nice picture, but it really doesn''t fit my understanding of the term anachronism.', '2007-04-02 12:41:03.000000', NULL, 1),
(3509978, 490601, 24454, '<td valign="top">What a REALLY cool photo.  Yes, the picnic table reflecting in that forest''s water is quite out of place -- but it looks amazing!  I love this.</td>', 'What a REALLY cool photo.  Yes, the picnic table reflecting in that forest''s water is quite out of place -- but it looks amazing!  I love this.', '2007-04-02 12:41:39.000000', NULL, 1),
(3509980, 491506, 69604, '<td valign="top">now thats funny I like it. the horse looks a bit scared, "wait where are you going to put THAT?"</td>', 'now thats funny I like it. the horse looks a bit scared, "wait where are you going to put THAT?"', '2007-04-02 12:42:21.000000', NULL, 1),
(3509981, 489900, 24454, '<td valign="top">Yes, that''s a great anachronism.   Nice car :)</td>', 'Yes, that''s a great anachronism.   Nice car :)', '2007-04-02 12:42:23.000000', NULL, 1),
(3509982, 489815, 69102, '<td valign="top">I get the idea that you were going for here, but the photograph itself is not very pleasing. The lighting is harsh and the placement of the shadows is distracting. The red ball isn''t prominent enough in the frame to stand as a strong enough subject on its own, but the surrounding ruin is too much of a jumble to give the eye somewhere to rest. A different time of day or a different angle might have made this much better.</td>', 'I get the idea that you were going for here, but the photograph itself is not very pleasing. The lighting is harsh and the placement of the shadows is distracting. The red ball isn''t prominent enough in the frame to stand as a strong enough subject on its own, but the surrounding ruin is too much of a jumble to give the eye somewhere to rest. A different time of day or a different angle might have made this much better.', '2007-04-02 12:43:26.000000', NULL, 1),
(3509983, 491271, 69604, '<td valign="top">its a nice picture, but it took me a bit to find the cell phone.</td>', 'its a nice picture, but it took me a bit to find the cell phone.', '2007-04-02 12:43:50.000000', NULL, 1),
(3509985, 491242, 45857, '<td valign="top">Perhaps a bit more of the clothing to set the context better, or maybe a contextual background.</td>', 'Perhaps a bit more of the clothing to set the context better, or maybe a contextual background.', '2007-04-02 12:44:16.000000', NULL, 1),
(3509986, 491206, 69604, '<td valign="top">does look old school, I like the way you used the color.</td>', 'does look old school, I like the way you used the color.', '2007-04-02 12:44:41.000000', NULL, 1),
(3509988, 490925, 36006, '<td valign="top">an interesting idea<br/> <br/>comp great, light barely noticeable to plane flat, nice movement, good lines, texture ok, overall a great attempt</td>', 'an interesting idea comp great, light barely noticeable to plane flat, nice movement, good lines, texture ok, overall a great attempt', '2007-04-02 12:45:00.000000', NULL, 1),
(3509989, 491474, 24454, '<td valign="top">This is just "my" kind of photo.  Candid.  On the street.  Sepia.  Interesting.   I LOVE IT!</td>', 'This is just "my" kind of photo.  Candid.  On the street.  Sepia.  Interesting.   I LOVE IT!', '2007-04-02 12:45:01.000000', NULL, 1),
(3509990, 491565, 69604, '<td valign="top">looks like you had fun.</td>', 'looks like you had fun.', '2007-04-02 12:45:06.000000', NULL, 1),
(3509992, 491089, 69102, '<td valign="top">The blown out background is a little overdone, and you''ve clipped portions of your subject with whatever you used to get the effect. Subject is strong, however. Although the composition seems a little too straightforward.</td>', 'The blown out background is a little overdone, and you''ve clipped portions of your subject with whatever you used to get the effect. Subject is strong, however. Although the composition seems a little too straightforward.', '2007-04-02 12:45:28.000000', NULL, 1),
(3509993, 490706, 40344, '<td valign="top">Fabulous!</td>', 'Fabulous!', '2007-04-02 12:45:34.000000', NULL, 1),
(3509994, 490601, 45857, '<td valign="top">Interesting setting, but not sure about the temporal dispalcement.</td>', 'Interesting setting, but not sure about the temporal dispalcement.', '2007-04-02 12:45:42.000000', NULL, 1),
(3509997, 491445, 24454, '<td valign="top">Tee hee. . .this is cute.  And perfect for this challenge!</td>', 'Tee hee. . .this is cute.  And perfect for this challenge!', '2007-04-02 12:46:03.000000', NULL, 1),
(3510000, 491363, 69102, '<td valign="top">Great shot. The slight counter clockwise tilt doesn''t work for me. I don''t think it adds to the shot and its distracting. Besides that, I really like it.</td>', 'Great shot. The slight counter clockwise tilt doesn''t work for me. I don''t think it adds to the shot and its distracting. Besides that, I really like it.', '2007-04-02 12:46:46.000000', NULL, 1),
(3510003, 490275, 24454, '<td valign="top">WOW!  This is AMAZING! What a striking composition.  And a perfect anachronism!  My favorite so far 10</td>', 'WOW!  This is AMAZING! What a striking composition.  And a perfect anachronism!  My favorite so far 10', '2007-04-02 12:47:33.000000', NULL, 1),
(3510004, 491584, 69102, '<td valign="top">Cool shot. Wish the jet at the left was a little less of a silloutte.</td>', 'Cool shot. Wish the jet at the left was a little less of a silloutte.', '2007-04-02 12:47:43.000000', NULL, 1),
(3510012, 489239, 36006, '<td valign="top">very interesting idea<br/> <br/>this took some time to pull together. great comp, excellent movement, great dof, lighting ok, blacks a bit deep, whites blown, good texture, overall a great attempt</td>', 'very interesting idea this took some time to pull together. great comp, excellent movement, great dof, lighting ok, blacks a bit deep, whites blown, good texture, overall a great attempt', '2007-04-02 12:49:52.000000', NULL, 1),
(3510016, 491203, 64929, '<td valign="top">Just a dang wonderful photo!  So appropriate to the challenge...so well done.  Bravo!  *10*</td>', 'Just a dang wonderful photo!  So appropriate to the challenge...so well done.  Bravo!  *10*', '2007-04-02 12:51:12.000000', NULL, 1),
(3510018, 489622, 45857, '<td valign="top">Interesting cultural statement, but how it shoehorns into this challenge alludes me.</td>', 'Interesting cultural statement, but how it shoehorns into this challenge alludes me.', '2007-04-02 12:51:33.000000', NULL, 1),
(3510021, 491506, 36006, '<td valign="top">a good image<br/> <br/>comp could be tighter, negative space on the left, color excellent, excellent texture, great lighting, good dof, great movement, very humorous, ok lines, overall a great attempt</td>', 'a good image comp could be tighter, negative space on the left, color excellent, excellent texture, great lighting, good dof, great movement, very humorous, ok lines, overall a great attempt', '2007-04-02 12:52:58.000000', NULL, 1),
(3510025, 490803, 45857, '<td valign="top">Nice old thing</td>', 'Nice old thing', '2007-04-02 12:54:10.000000', NULL, 1),
(3510030, 491429, 69102, '<td valign="top">Couple of things that aren''t working for me in this shot: First, the composition seems really off and out of balance. The statue and building elements in the right and lower right are really heavy and the negative space in the upper left doesn''t offset them. If you could have managed an angle that would have placed the tower further to the left of the frame, that might have helped. Second, it looks as if you have either desaturated the statue or it is being lit differently from the background buildings. This gives the effect of the statue not being a true part of the composition, but rather something that was cut and paste in. (Note, I''m not saying that you did PS the statue in, just that the color and light on the statue give that impression.) This detracts from the impressiveness of the angles used to achieve this natural composition. One other thing, while the subjects do seem out of time to the present, I don''t know that they are readily out of time to each other. Seems like there is a lot of potential here, but the execution needs work.</td>', 'Couple of things that aren''t working for me in this shot: First, the composition seems really off and out of balance. The statue and building elements in the right and lower right are really heavy and the negative space in the upper left doesn''t offset them. If you could have managed an angle that would have placed the tower further to the left of the frame, that might have helped. Second, it looks as if you have either desaturated the statue or it is being lit differently from the background buildings. This gives the effect of the statue not being a true part of the composition, but rather something that was cut and paste in. (Note, I''m not saying that you did PS the statue in, just that the color and light on the statue give that impression.) This detracts from the impressiveness of the angles used to achieve this natural composition. One other thing, while the subjects do seem out of time to the present, I don''t know that they are readily out of time to each other. Seems like there is a lot of potential here, but the execution needs work.', '2007-04-02 12:56:14.000000', NULL, 1),
(3510035, 491506, 45857, '<td valign="top">Very good idea, and good shot.<br/>(Wild Lars, fastest gun west of Reykjavik! LOL)7</td>', 'Very good idea, and good shot.(Wild Lars, fastest gun west of Reykjavik! LOL)7', '2007-04-02 12:59:53.000000', NULL, 1),
(3510039, 491483, 69102, '<td valign="top">The pot is certainly out of time to the present, but it isn''t apparent that it is out of time to any of the other elements in the environment of the shot. As to the picture, I wish there had been a little deeper DOF to keep the cups in focus, the lighting on the pot is too harsh, and (while they may have been intentional) the reflections on the background above and behind the pot don''t work for me.</td>', 'The pot is certainly out of time to the present, but it isn''t apparent that it is out of time to any of the other elements in the environment of the shot. As to the picture, I wish there had been a little deeper DOF to keep the cups in focus, the lighting on the pot is too harsh, and (while they may have been intentional) the reflections on the background above and behind the pot don''t work for me.', '2007-04-02 13:00:25.000000', NULL, 1),
(3510044, 491438, 73559, '<td valign="top">I have been watching this photograph for 15 minutes before assigning my vote, which is 10. It is a simple composition, but at the same time a phantastic image. The message it contains is clear and readable. In other words, there is culture behind it. There seems to be little or perhaps no post-processing, which makes it even more interesting in my opinion. Best wishes to the author!</td>', 'I have been watching this photograph for 15 minutes before assigning my vote, which is 10. It is a simple composition, but at the same time a phantastic image. The message it contains is clear and readable. In other words, there is culture behind it. There seems to be little or perhaps no post-processing, which makes it even more interesting in my opinion. Best wishes to the author!', '2007-04-02 13:02:33.000000', NULL, 1),
(3510047, 491067, 45857, '<td valign="top">Love the shot and your treatment</td>', 'Love the shot and your treatment', '2007-04-02 13:02:57.000000', NULL, 1),
(3510053, 491361, 45857, '<td valign="top">Really subtle</td>', 'Really subtle', '2007-04-02 13:04:23.000000', NULL, 1),
(3510057, 491258, 69102, '<td valign="top">Cool shot. I wish the guy was a little more seprated from the background. His arm and the hill behind sort of blend together. Moving him a little right (or the camera a little left), might have solved this.</td>', 'Cool shot. I wish the guy was a little more seprated from the background. His arm and the hill behind sort of blend together. Moving him a little right (or the camera a little left), might have solved this.', '2007-04-02 13:05:36.000000', NULL, 1),
(3510058, 490601, 69102, '<td valign="top">I had the same sort of an idea for my shot, but this is executed much better than mine. Very nice! - 8</td>', 'I had the same sort of an idea for my shot, but this is executed much better than mine. Very nice! - 8', '2007-04-02 13:06:45.000000', NULL, 1),
(3510062, 491271, 69102, '<td valign="top">Good idea, and technically this is a very well done photo. However, I wish that the phone had been more prominent somehow. Had to search for a second before I caught it. Perhaps a couple of retail boxes of phones or other electronics would have made the point more clearly and obviously. - 6</td>', 'Good idea, and technically this is a very well done photo. However, I wish that the phone had been more prominent somehow. Had to search for a second before I caught it. Perhaps a couple of retail boxes of phones or other electronics would have made the point more clearly and obviously. - 6', '2007-04-02 13:09:13.000000', NULL, 1),
(3510067, 490237, 69102, '<td valign="top">Pretty much all seem to be in the same category to me. ;)</td>', 'Pretty much all seem to be in the same category to me. ;)', '2007-04-02 13:10:56.000000', NULL, 1),
(3510069, 491590, 69102, '<td valign="top">Cool idea. It''s not entirely obvious that the person is using a quill, however. Although the names on the phone also put the point across.</td>', 'Cool idea. It''s not entirely obvious that the person is using a quill, however. Although the names on the phone also put the point across.', '2007-04-02 13:12:03.000000', NULL, 1),
(3510070, 491402, 67152, '<td valign="top">i like the lighting on Capone''s face a lot, but I think a little more light on the ear piece would make this come off a little better - it is just a little dark on my monitor and fear it would be worse on others.  Gets a 9 from me</td>', 'i like the lighting on Capone''s face a lot, but I think a little more light on the ear piece would make this come off a little better - it is just a little dark on my monitor and fear it would be worse on others.  Gets a 9 from me', '2007-04-02 13:12:32.000000', NULL, 1),
(3510075, 491565, 69102, '<td valign="top">This had to be fun to shoot! :)</td>', 'This had to be fun to shoot! :)', '2007-04-02 13:13:11.000000', NULL, 1),
(3510076, 491363, 47316, '<td valign="top">Cool location and nice lighting. You clearly met and understood the challenge. Feels a little lacking to me as far as interest goes, but an overall nice photograph.</td>', 'Cool location and nice lighting. You clearly met and understood the challenge. Feels a little lacking to me as far as interest goes, but an overall nice photograph.', '2007-04-02 13:13:28.000000', NULL, 1),
(3510077, 490378, 47316, '<td valign="top">Seems to washed out and lacking in tonal range. Could really use some contrast.</td>', 'Seems to washed out and lacking in tonal range. Could really use some contrast.', '2007-04-02 13:14:05.000000', NULL, 1),
(3510080, 489390, 69102, '<td valign="top">The PP makes this a really "flat" photo. Nothing stands out and it becomes hard to distinguish between the elements involved. Effect reminds me (not unpleasantly) of some types of 60s/70s pop art, but it doesn''t work for me here.</td>', 'The PP makes this a really "flat" photo. Nothing stands out and it becomes hard to distinguish between the elements involved. Effect reminds me (not unpleasantly) of some types of 60s/70s pop art, but it doesn''t work for me here.', '2007-04-02 13:15:05.000000', NULL, 1),
(3510081, 491548, 47316, '<td valign="top">Nothing seems out of place in time, just 2 different types of money. Though they may be new and old there isn''t any context for either to seem out of place of. Overal an unintesting photograph.</td>', 'Nothing seems out of place in time, just 2 different types of money. Though they may be new and old there isn''t any context for either to seem out of place of. Overal an unintesting photograph.', '2007-04-02 13:15:16.000000', NULL, 1),
(3510084, 491206, 47316, '<td valign="top">Not a fan of the redish post-processing. Would have worked much better for me with just a crisp black and white.</td>', 'Not a fan of the redish post-processing. Would have worked much better for me with just a crisp black and white.', '2007-04-02 13:16:23.000000', NULL, 1),
(3510089, 491271, 47316, '<td valign="top">Nice composition and lighting. Would like to see a bit more contrast. The phone works for anachronism but really it''s not a very interesting addition to the photograph. Seems thrown in. This would have made more sense for me if one of the shelves was maybe stocked with a modern day grocery item, something obscenely out of place (like cheese wiz or lunchables or something).</td>', 'Nice composition and lighting. Would like to see a bit more contrast. The phone works for anachronism but really it''s not a very interesting addition to the photograph. Seems thrown in. This would have made more sense for me if one of the shelves was maybe stocked with a modern day grocery item, something obscenely out of place (like cheese wiz or lunchables or something).', '2007-04-02 13:19:51.000000', NULL, 1),
(3510092, 491203, 47316, '<td valign="top">Nicely done. The background is perfect and the costume! Lucky to have something cool like that (or rent or whatever you may have done... lol!) I''m more a fan of eye contact but the solemn look works.</td>', 'Nicely done. The background is perfect and the costume! Lucky to have something cool like that (or rent or whatever you may have done... lol!) I''m more a fan of eye contact but the solemn look works.', '2007-04-02 13:21:12.000000', NULL, 1),
(3510096, 491361, 69102, '<td valign="top">A very beautiful picture, but the anachronistic nature of the shot just doesn''t jump out at me.</td>', 'A very beautiful picture, but the anachronistic nature of the shot just doesn''t jump out at me.', '2007-04-02 13:23:16.000000', NULL, 1),
(3510097, 491258, 47316, '<td valign="top">I''m not really understanding the anachronism here. He is certainly misplaced but it seems in location not time.<br/> <br/>As for the photograph, the reflections and the sky are nice and the pose seems pretty relaxed.</td>', 'I''m not really understanding the anachronism here. He is certainly misplaced but it seems in location not time. As for the photograph, the reflections and the sky are nice and the pose seems pretty relaxed.', '2007-04-02 13:23:24.000000', NULL, 1),
(3510099, 490788, 30049, '<td valign="top">I think this is a great idea and you did a nice job with the photo.  The problem is going to be the flash drive.  Many aren''t going to recognize it or see it for what it represents IMO.  It''s a very small part of the composition.  Good luck in the challenge.</td>', 'I think this is a great idea and you did a nice job with the photo.  The problem is going to be the flash drive.  Many aren''t going to recognize it or see it for what it represents IMO.  It''s a very small part of the composition.  Good luck in the challenge.', '2007-04-02 13:23:43.000000', NULL, 1),
(3510100, 489622, 47316, '<td valign="top">More of a misplaced purpose than misplaced in time.</td>', 'More of a misplaced purpose than misplaced in time.', '2007-04-02 13:23:44.000000', NULL, 1),
(3510105, 489622, 66353, '<td valign="top">I fail to see the anachronism I''m afraid</td>', 'I fail to see the anachronism I''m afraid', '2007-04-02 13:24:41.000000', NULL, 1),
(3510107, 490333, 66353, '<td valign="top">I fail to see the anachronism I''m afraid</td>', 'I fail to see the anachronism I''m afraid', '2007-04-02 13:24:55.000000', NULL, 1),
(3510108, 491249, 66353, '<td valign="top">I fail to see the anachronism I''m afraid</td>', 'I fail to see the anachronism I''m afraid', '2007-04-02 13:25:08.000000', NULL, 1),
(3510110, 490333, 47316, '<td valign="top">I don''t see an anachronism at all. More of a cultural difference than a time diference, and even that is not displayed, it is shoehorned with the title. The editing seems odd, such as her skin tones and the smudges (like on her cheek).</td>', 'I don''t see an anachronism at all. More of a cultural difference than a time diference, and even that is not displayed, it is shoehorned with the title. The editing seems odd, such as her skin tones and the smudges (like on her cheek).', '2007-04-02 13:26:04.000000', NULL, 1),
(3510111, 490275, 60141, '<td valign="top">Love the image, cool subject.  It''ll be interesting to see where this is.  Not crazy about the title.</td>', 'Love the image, cool subject.  It''ll be interesting to see where this is.  Not crazy about the title.', '2007-04-02 13:26:19.000000', NULL, 1),
(3510113, 490894, 66353, '<td valign="top">I fail to see the anachronism I''m afraid</td>', 'I fail to see the anachronism I''m afraid', '2007-04-02 13:26:31.000000', NULL, 1),
(3510115, 491203, 69102, '<td valign="top">Great shot. The overcast sky and the color tones also work to evoke English countryside.</td>', 'Great shot. The overcast sky and the color tones also work to evoke English countryside.', '2007-04-02 13:26:48.000000', NULL, 1),
(3510118, 491452, 69102, '<td valign="top">Cool shot. Could be a movie still out of a Michael Crichton vehicle.</td>', 'Cool shot. Could be a movie still out of a Michael Crichton vehicle.', '2007-04-02 13:27:59.000000', NULL, 1),
(3510121, 491383, 60141, '<td valign="top">that''s hysterical!</td>', 'that''s hysterical!', '2007-04-02 13:28:26.000000', NULL, 1),
