(3516117, 491361, 70000, '<td valign="top">I think this would have had more of an impact if you showed more of the fence and house and less sky</td>', 'I think this would have had more of an impact if you showed more of the fence and house and less sky', '2007-04-03 21:15:58.000000', NULL, 1),
(3516118, 491203, 70000, '<td valign="top">great costumes, perfect for this compatition</td>', 'great costumes, perfect for this compatition', '2007-04-03 21:16:21.000000', NULL, 1),
(3516120, 491506, 70000, '<td valign="top">HAHAHA nice lighting. cute</td>', 'HAHAHA nice lighting. cute', '2007-04-03 21:16:54.000000', NULL, 1),
