(3516130, 491258, 70000, '<td valign="top">The right side of the picture is really blown which is a shame because this is a beautiful brilliant shot</td>', 'The right side of the picture is really blown which is a shame because this is a beautiful brilliant shot', '2007-04-03 21:20:02.000000', NULL, 1),
(3516174, 491495, 66348, '<td valign="top">I really like the antique feeling of this shot. The woman with the bathing suit really pops at you, it has great composition and I really like the DOF and vignetting around your image. The sepia adds a great deal to the shot, especially with the editing of bringing in the color. A great expression on the girls face, and I think the person on the left is spying on you. Well done. 10</td>', 'I really like the antique feeling of this shot. The woman with the bathing suit really pops at you, it has great composition and I really like the DOF and vignetting around your image. The sepia adds a great deal to the shot, especially with the editing of bringing in the color. A great expression on the girls face, and I think the person on the left is spying on you. Well done. 10', '2007-04-03 21:42:00.000000', NULL, 1),
(3516560, 491506, 73828, '<td valign="top">Good! Very good!!!</td>', 'Good! Very good!!!', '2007-04-03 23:37:37.000000', NULL, 1),
(3516577, 491529, 73828, '<td valign="top">I love the Symbological division and sharingness of both past and present in this picture. None is out of importance. Both equally necessary.</td>', 'I love the Symbological division and sharingness of both past and present in this picture. None is out of importance. Both equally necessary.', '2007-04-03 23:49:18.000000', NULL, 1),
(3517208, 491546, 53316, '<td valign="top">I bet you''re getting DNMC''ed for this even though it does technically meet the challenge description. I hope not though.</td>', 'I bet you''re getting DNMC''ed for this even though it does technically meet the challenge description. I hope not though.', '2007-04-04 02:43:17.000000', NULL, 1),
(3517380, 490812, 57646, '<td valign="top">The composition is good, and I like the clarity against the (apparently) Southern Mountain backdrop. The title fits the picture.</td>', 'The composition is good, and I like the clarity against the (apparently) Southern Mountain backdrop. The title fits the picture.', '2007-04-04 03:44:34.000000', NULL, 1),
