(3520897, 491067, 65234, '<td valign="top">Old ship, modern building, works for me.  I like the lighting and sepia.</td>', 'Old ship, modern building, works for me.  I like the lighting and sepia.', '2007-04-04 23:48:24.000000', NULL, 1),
(3520905, 490601, 65234, '<td valign="top">Lovely image and quite interesting.  Seems more out of place than out of time so I''m not sure it''s really anachronistic.</td>', 'Lovely image and quite interesting.  Seems more out of place than out of time so I''m not sure it''s really anachronistic.', '2007-04-04 23:49:29.000000', NULL, 1),
(3520915, 491452, 65234, '<td valign="top">Yay, a real anachronism!</td>', 'Yay, a real anachronism!', '2007-04-04 23:51:32.000000', NULL, 1),
(3520917, 491483, 65234, '<td valign="top">Lighting and reflections are harsh.</td>', 'Lighting and reflections are harsh.', '2007-04-04 23:52:10.000000', NULL, 1),
(3520921, 491593, 65234, '<td valign="top">Excellent take on the challenge!</td>', 'Excellent take on the challenge!', '2007-04-04 23:52:33.000000', NULL, 1),
(3520925, 490378, 65234, '<td valign="top">The clock does seem very wrong in proximity to the pagoda.</td>', 'The clock does seem very wrong in proximity to the pagoda.', '2007-04-04 23:53:12.000000', NULL, 1),
(3520936, 491584, 65234, '<td valign="top">Great idea; could use a bit more detail.</td>', 'Great idea; could use a bit more detail.', '2007-04-04 23:54:59.000000', NULL, 1),
(3520940, 491477, 65234, '<td valign="top">I''d like this better if the Roman soldier were next to the modern policemen on the motorcycle back there.</td>', 'I''d like this better if the Roman soldier were next to the modern policemen on the motorcycle back there.', '2007-04-04 23:56:16.000000', NULL, 1),
(3520948, 490812, 65234, '<td valign="top">I get the concept, but it might have been better with something in the picture that looked modern to give it context.</td>', 'I get the concept, but it might have been better with something in the picture that looked modern to give it context.', '2007-04-04 23:57:27.000000', NULL, 1),
(3520952, 490925, 65234, '<td valign="top">Very creative.</td>', 'Very creative.', '2007-04-04 23:57:59.000000', NULL, 1),
(3520961, 490724, 65234, '<td valign="top">Fits the challenge, but somehow I want the contrast between the well and the modern building to be stronger.  All the vegetation is distracting.  Maybe a different perspective?</td>', 'Fits the challenge, but somehow I want the contrast between the well and the modern building to be stronger.  All the vegetation is distracting.  Maybe a different perspective?', '2007-04-04 23:59:46.000000', NULL, 1),
(3520964, 490408, 65234, '<td valign="top">Nice capture for this challenge.</td>', 'Nice capture for this challenge.', '2007-04-05 00:01:19.000000', NULL, 1),
(3520966, 491565, 65234, '<td valign="top">Good image for this.  Like the DOF to make them stand out while keeping plenty of context from the background.</td>', 'Good image for this.  Like the DOF to make them stand out while keeping plenty of context from the background.', '2007-04-05 00:02:50.000000', NULL, 1),
(3520975, 491363, 65234, '<td valign="top">This one is making me hum the old Sesame Street song: "One of these things is not like the others, one of these things just doesn''t belong."  Nicely done, even if I am going to have that song stuck in my head ;-)</td>', 'This one is making me hum the old Sesame Street song: "One of these things is not like the others, one of these things just doesn''t belong."  Nicely done, even if I am going to have that song stuck in my head ;-)', '2007-04-05 00:04:48.000000', NULL, 1),
(3520976, 491203, 65234, '<td valign="top">Lovely greens and great contrast with the city.</td>', 'Lovely greens and great contrast with the city.', '2007-04-05 00:05:47.000000', NULL, 1),
(3520981, 491284, 65234, '<td valign="top">Very nicely done.  Perfect composition to draw the eye instantly to the Geishas and then around to the modern crowd.  Including what appears to be a NY Yankees cap!</td>', 'Very nicely done.  Perfect composition to draw the eye instantly to the Geishas and then around to the modern crowd.  Including what appears to be a NY Yankees cap!', '2007-04-05 00:08:09.000000', NULL, 1),
(3520982, 491350, 65234, '<td valign="top">Nice find.</td>', 'Nice find.', '2007-04-05 00:09:00.000000', NULL, 1),
(3520990, 491446, 65234, '<td valign="top">Good subject; lighting is pretty uneven.  I wonder if a fill flash would have worked?</td>', 'Good subject; lighting is pretty uneven.  I wonder if a fill flash would have worked?', '2007-04-05 00:11:02.000000', NULL, 1),
(3520997, 490238, 65234, '<td valign="top">Great subject but focus doesn''t seem sharpest on the classic car and shot could use a bit more light to bring out detail.</td>', 'Great subject but focus doesn''t seem sharpest on the classic car and shot could use a bit more light to bring out detail.', '2007-04-05 00:12:59.000000', NULL, 1),
