(3521404, 491401, 74037, '<td valign="top">great capture.</td>', 'great capture.', '2007-04-05 03:49:03.000000', NULL, 1),
(3521414, 491423, 74037, '<td valign="top">definitely lens cleaning time.</td>', 'definitely lens cleaning time.', '2007-04-05 03:56:18.000000', NULL, 1),
(3521513, 490187, 70661, '<td valign="top">Great job! One of my favorites!</td>', 'Great job! One of my favorites!', '2007-04-05 06:53:16.000000', NULL, 1),
(3521514, 491203, 70661, '<td valign="top">I really like this. You did a great job.</td>', 'I really like this. You did a great job.', '2007-04-05 06:53:56.000000', NULL, 1),
(3521903, 490132, 74137, '<td valign="top">I like the idea but the lighting is kind of flat.  The image would work better if it was captured at a different time during the day (dusk).  The image needs to be sharper.  The textures in the stump is lost due to softness in focus.</td>', 'I like the idea but the lighting is kind of flat.  The image would work better if it was captured at a different time during the day (dusk).  The image needs to be sharper.  The textures in the stump is lost due to softness in focus.', '2007-04-05 10:47:34.000000', NULL, 1),
(3521921, 490530, 74137, '<td valign="top">Great job with the POV. Good Photo</td>', 'Great job with the POV. Good Photo', '2007-04-05 10:55:03.000000', NULL, 1),
(3521963, 490788, 39144, '<td valign="top">Definitely a ribbon winner here. Your subject is awesome. I like the subtle hint with the flash drive. The lighting is perfect. Even throughout the important parts of whatever that thing is under the flash drive. :) The the control over DOF was put to very good use in this. Nice job.</td>', 'Definitely a ribbon winner here. Your subject is awesome. I like the subtle hint with the flash drive. The lighting is perfect. Even throughout the important parts of whatever that thing is under the flash drive. :) The the control over DOF was put to very good use in this. Nice job.', '2007-04-05 11:17:01.000000', NULL, 1),
(3521968, 491301, 39144, '<td valign="top">Very creative. You did a good job on this shot. The low angle really makes the person stand out. Geed even lighting throught the photo, including the sky must have been difficult to achieve. Nice job.</td>', 'Very creative. You did a good job on this shot. The low angle really makes the person stand out. Geed even lighting throught the photo, including the sky must have been difficult to achieve. Nice job.', '2007-04-05 11:18:57.000000', NULL, 1),
(3521970, 491529, 39144, '<td valign="top">What a fantastic architecture shot. Awesome job.</td>', 'What a fantastic architecture shot. Awesome job.', '2007-04-05 11:19:42.000000', NULL, 1),
(3521971, 491363, 39144, '<td valign="top">What a n awesome setup. How did you find such a place? And the lighting is awesome! Really good work.</td>', 'What a n awesome setup. How did you find such a place? And the lighting is awesome! Really good work.', '2007-04-05 11:20:48.000000', NULL, 1),
(3521979, 490275, 39144, '<td valign="top">This is an excellent shot. The lighting seems perfect. The shadows are dark, but still maintain detail, and the highlights dont appear blown out. What an accomplishment!</td>', 'This is an excellent shot. The lighting seems perfect. The shadows are dark, but still maintain detail, and the highlights dont appear blown out. What an accomplishment!', '2007-04-05 11:23:24.000000', NULL, 1),
(3521981, 491617, 39144, '<td valign="top">This would be a great product shot for an ad. Nice work!</td>', 'This would be a great product shot for an ad. Nice work!', '2007-04-05 11:24:30.000000', NULL, 1),
(3522461, 491301, 69448, '<td valign="top">I think it is too much flash, that hits the road. Very nice composition though!</td>', 'I think it is too much flash, that hits the road. Very nice composition though!', '2007-04-05 14:42:21.000000', NULL, 1),
(3522473, 491617, 69448, '<td valign="top">Great idea, nice colours and depth of field!</td>', 'Great idea, nice colours and depth of field!', '2007-04-05 14:45:23.000000', NULL, 1),
(3522537, 491404, 69448, '<td valign="top">Spännande idé. Skulle vara roligt att se fabriken också.<br/>Hehe, var det alla svenskar som dog under 2a världskriget?</td>', 'Spännande idé. Skulle vara roligt att se fabriken också.Hehe, var det alla svenskar som dog under 2a världskriget?', '2007-04-05 15:02:45.000000', NULL, 1),
(3522581, 490601, 1031, '<td valign="top">It''s no fun trying to eat with a snorkel on ... : )</td>', 'It''s no fun trying to eat with a snorkel on ... : )', '2007-04-05 15:21:43.000000', NULL, 1),
(3522585, 490846, 32338, '<td valign="top">This is a neat affect.</td>', 'This is a neat affect.', '2007-04-05 15:22:29.000000', NULL, 1),
(3522595, 490894, 32338, '<td valign="top">Honestly, it took me a while to see the anachronism.</td>', 'Honestly, it took me a while to see the anachronism.', '2007-04-05 15:26:06.000000', NULL, 1),
(3522596, 491203, 1031, '<td valign="top">Keeping the mail from rusting up in that environment must be quite a challenge! I figured that SCA members would have an advantage in this particular competition.</td>', 'Keeping the mail from rusting up in that environment must be quite a challenge! I figured that SCA members would have an advantage in this particular competition.', '2007-04-05 15:26:56.000000', NULL, 1),
(3522599, 491494, 32338, '<td valign="top">I see your point.</td>', 'I see your point.', '2007-04-05 15:28:16.000000', NULL, 1),
(3522602, 490601, 32338, '<td valign="top">I like this.  I think that a slightly different perspective would make it even better.  -Perhaps table lower in the image (omit the table reflection) with more trees/water.</td>', 'I like this.  I think that a slightly different perspective would make it even better.  -Perhaps table lower in the image (omit the table reflection) with more trees/water.', '2007-04-05 15:31:37.000000', NULL, 1),
(3522603, 490706, 32338, '<td valign="top">Oh wow, its nearly surreal!</td>', 'Oh wow, its nearly surreal!', '2007-04-05 15:32:26.000000', NULL, 1),
(3522604, 491617, 32338, '<td valign="top">Cute composition</td>', 'Cute composition', '2007-04-05 15:33:07.000000', NULL, 1),
(3522605, 491590, 32338, '<td valign="top">Good idea.</td>', 'Good idea.', '2007-04-05 15:33:46.000000', NULL, 1),
(3522615, 491284, 1031, '<td valign="top">I don''t know if you partially desaturated the "other people" or if that''s just how the scene photographed, but it''s very effective at making your subjects stand out from the crowd.</td>', 'I don''t know if you partially desaturated the "other people" or if that''s just how the scene photographed, but it''s very effective at making your subjects stand out from the crowd.', '2007-04-05 15:38:15.000000', NULL, 1),
(3522626, 490846, 1031, '<td valign="top">Interested to see how this was filtered -- my first guess involves Find Edges. Clever use of ultra-wide angle.</td>', 'Interested to see how this was filtered -- my first guess involves Find Edges. Clever use of ultra-wide angle.', '2007-04-05 15:41:53.000000', NULL, 1),
(3522630, 489239, 1031, '<td valign="top">Certainly plenty of bad news to go around ... I remember both of these : (</td>', 'Certainly plenty of bad news to go around ... I remember both of these : (', '2007-04-05 15:43:49.000000', NULL, 1),
(3522635, 490237, 1031, '<td valign="top">"Economy Edition" -- that one''s great, even if it''s not "the one" you meant : )</td>', '"Economy Edition" -- that one''s great, even if it''s not "the one" you meant : )', '2007-04-05 15:46:02.000000', NULL, 1),
(3522642, 491565, 1031, '<td valign="top">I''m surprised you/your models got past security with that stuff!<br/> <br/>Scale armor always made sense to me -- it combines the best aspects of both mail and plate; besides, if scales were good enough for the dinosaurs ... : )</td>', 'I''m surprised you/your models got past security with that stuff! Scale armor always made sense to me -- it combines the best aspects of both mail and plate; besides, if scales were good enough for the dinosaurs ... : )', '2007-04-05 15:50:06.000000', NULL, 1),
(3522666, 491401, 1031, '<td valign="top">Nice assortment of warplanes -- good timing for this to show up this week!</td>', 'Nice assortment of warplanes -- good timing for this to show up this week!', '2007-04-05 16:02:07.000000', NULL, 1),
(3522979, 491203, 30982, '<td valign="top">My favorite of the challenge for a couple of reasons.  First, it''s a great shot.  Second, and most importantly, the longing is tangible here - one can feel this gentleman''s need to return to his time and place.  Very nicely done, both for this specific challenge and as a standalone shot.</td>', 'My favorite of the challenge for a couple of reasons.  First, it''s a great shot.  Second, and most importantly, the longing is tangible here - one can feel this gentleman''s need to return to his time and place.  Very nicely done, both for this specific challenge and as a standalone shot.', '2007-04-05 17:31:15.000000', NULL, 1),
(3522982, 491527, 30982, '<td valign="top">I quite like the odd angle, the reflection, the missing pane, and of course the robodog.  Very well done.</td>', 'I quite like the odd angle, the reflection, the missing pane, and of course the robodog.  Very well done.', '2007-04-05 17:31:41.000000', NULL, 1),
(3522988, 491284, 30982, '<td valign="top">A very interesting shot - definitely meets the challenge.  And I wonder what the folks in the back are looking at.</td>', 'A very interesting shot - definitely meets the challenge.  And I wonder what the folks in the back are looking at.', '2007-04-05 17:32:12.000000', NULL, 1),
(3522993, 491565, 30982, '<td valign="top">This is perfect!  And very fun.  How did you get the ax past mall security??</td>', 'This is perfect!  And very fun.  How did you get the ax past mall security??', '2007-04-05 17:32:44.000000', NULL, 1),
(3522995, 491375, 30982, '<td valign="top">Nifty idea, and well executed.</td>', 'Nifty idea, and well executed.', '2007-04-05 17:32:58.000000', NULL, 1),
(3522999, 491402, 30982, '<td valign="top">Subtle and well photographed.</td>', 'Subtle and well photographed.', '2007-04-05 17:33:17.000000', NULL, 1),
(3523005, 491452, 30982, '<td valign="top">Oneof my top picks - nicely done, definitely meets the challenge.  And the model is cute.  :-)</td>', 'Oneof my top picks - nicely done, definitely meets the challenge.  And the model is cute.  :-)', '2007-04-05 17:34:18.000000', NULL, 1),
(3523008, 491067, 30982, '<td valign="top">I suspect Firsty.  Lovely light, wonderful tones, and quite the shot to meet the challenge.</td>', 'I suspect Firsty.  Lovely light, wonderful tones, and quite the shot to meet the challenge.', '2007-04-05 17:34:45.000000', NULL, 1),
(3523046, 491375, 56797, '<td valign="top">VERY nice shot. beautiful, sharp and has just a really great feel/mood to it.</td>', 'VERY nice shot. beautiful, sharp and has just a really great feel/mood to it.', '2007-04-05 17:45:27.000000', NULL, 1);
