(3531176, 491495, 67697, '<td valign="top">What a great classic picture!</td>', 'What a great classic picture!', '2007-04-09 00:20:22.000000', NULL, 1),
(3531180, 491089, 67697, '<td valign="top">Haha - how many kids did not get the 8-track part?  Or even that it''s of the BeeGees? :D</td>', 'Haha - how many kids did not get the 8-track part?  Or even that it''s of the BeeGees? :D', '2007-04-09 00:21:16.000000', NULL, 1),
(3531181, 491168, 63503, '<td valign="top">I am missing the anachronism here</td>', 'I am missing the anachronism here', '2007-04-09 00:21:23.000000', NULL, 1),
(3531184, 491474, 67697, '<td valign="top">I just love this picture for some reason.  It''s very striking and really piques your curiosity.</td>', 'I just love this picture for some reason.  It''s very striking and really piques your curiosity.', '2007-04-09 00:22:03.000000', NULL, 1),
(3531189, 491403, 63503, '<td valign="top">Nice picture, but if you hadn''t told me that it was Silicon Valley I would have seen nothing anachronic here</td>', 'Nice picture, but if you hadn''t told me that it was Silicon Valley I would have seen nothing anachronic here', '2007-04-09 00:23:01.000000', NULL, 1),
(3531190, 491310, 67697, '<td valign="top">Nice constrast of subjects.  A very simple and effective idea.  Great clarity and color!</td>', 'Nice constrast of subjects.  A very simple and effective idea.  Great clarity and color!', '2007-04-09 00:23:07.000000', NULL, 1),
