INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3531374, 491529, 42013, '<td valign="top">Awesome Robert. Nice score fellow F-stopper.</td>', 'Awesome Robert. Nice score fellow F-stopper.', '2007-04-09 01:28:31.000000', NULL, 0),
(3531386, 491203, 60495, '<td valign="top">Nicely done, the only 10 I gave in this challenge, not to take anything away from the blue ribbon picture, I did give it a 9, but this was my top pick! Congratulations on your first ribbon.</td>', 'Nicely done, the only 10 I gave in this challenge, not to take anything away from the blue ribbon picture, I did give it a 9, but this was my top pick! Congratulations on your first ribbon.', '2007-04-09 01:31:54.000000', NULL, 0),
(3531402, 491203, 62727, '<td valign="top">Congrats on your first ribbon!  Well deserved!</td>', 'Congrats on your first ribbon!  Well deserved!', '2007-04-09 01:35:20.000000', NULL, 0),
(3531411, 491067, 51793, '<td valign="top">Man you are just all kinds of lucky with that opera house aren''t you???</td>', 'Man you are just all kinds of lucky with that opera house aren''t you???', '2007-04-09 01:37:51.000000', NULL, 0),
(3531415, 491203, 74037, '<td valign="top">Great pic. Congrats on your first ribbon.</td>', 'Great pic. Congrats on your first ribbon.', '2007-04-09 01:38:39.000000', NULL, 0),
(3531424, 490187, 40718, '<td valign="top">Your shot was perfectly what I had in my mind''s eye.  Should have ribboned.</td>', 'Your shot was perfectly what I had in my mind''s eye.  Should have ribboned.', '2007-04-09 01:41:22.000000', NULL, 0),
(3531450, 491452, 51750, '<td valign="top">This in my opinion really is better than any of the photos in this challenge too bad the voters didnt think the same as me...</td>', 'This in my opinion really is better than any of the photos in this challenge too bad the voters didnt think the same as me...', '2007-04-09 01:49:18.000000', NULL, 0),
(3531464, 491527, 30982, '<td valign="top">Well, I''ll be... this was you?  I hate to tell you this (it''ll do nasty things to your ego) but if pressed I''d probably have guessed bucket.</td>', 'Well, I''ll be... this was you?  I hate to tell you this (it''ll do nasty things to your ego) but if pressed I''d probably have guessed bucket.', '2007-04-09 01:52:55.000000', NULL, 0),
(3531486, 491529, 22301, '<td valign="top">Way to go Robert! Glad to see this finish so well.</td>', 'Way to go Robert! Glad to see this finish so well.', '2007-04-09 01:58:00.000000', NULL, 0),
(3531488, 491067, 75179, '<td valign="top">That is an amazing picture, just beautiful!</td>', 'That is an amazing picture, just beautiful!', '2007-04-09 01:58:24.000000', NULL, 0),
(3531550, 491249, 53316, '<td valign="top">SOOOO underrated.</td>', 'SOOOO underrated.', '2007-04-09 02:14:07.000000', NULL, 0),
(3531554, 491258, 20168, '<td valign="top">Hey Thomas, Congrats on another top 20 finish! Fun photo shoot too!</td>', 'Hey Thomas, Congrats on another top 20 finish! Fun photo shoot too!', '2007-04-09 02:15:49.000000', NULL, 0),
(3531587, 491067, 48228, '<td valign="top">Definately a winner in my book, and so worth the <b>"Blue Ribbon"..... </b> <br/>You are a <b>"Master"</b> in my eyes, re images of our famous <b>"Opera House"</b>, especially colortoned like this, with the old sailing ship alongside. <br/>Well done buddy, and we are so very proud of you.....<br/>Thank you also for sharing your location, and some of you photographic secrets..... You are <b>"TOPS"</b> in my book.....<br/><br/><i>Message edited by author 2007-04-09 01:32:58.</i></td>', 'Definately a winner in my book, and so worth the "Blue Ribbon".....  You are a "Master" in my eyes, re images of our famous "Opera House", especially colortoned like this, with the old sailing ship alongside. Well done buddy, and we are so very proud of you.....Thank you also for sharing your location, and some of you photographic secrets..... You are "TOPS" in my book.....', '2007-04-09 02:30:10.000000', '2007-04-09 02:32:58.000000', 0),
(3531602, 491506, 3214, '<td valign="top">Very cool concept and execution.  I rode my horse through a Taco Bell drive-through once, in the mid-90s. Now they''d probably have a fit.  Congrats on your top ten.</td>', 'Very cool concept and execution.  I rode my horse through a Taco Bell drive-through once, in the mid-90s. Now they''d probably have a fit.  Congrats on your top ten.', '2007-04-09 02:39:36.000000', NULL, 0),
(3531609, 491067, 33352, '<td valign="top">Great work Kieth,well deserving of the Blue...</td>', 'Great work Kieth,well deserving of the Blue...', '2007-04-09 02:46:04.000000', NULL, 0),
(3531610, 491203, 33352, '<td valign="top">It was a toss up between you or the blue winner, there should be two in this challenge.</td>', 'It was a toss up between you or the blue winner, there should be two in this challenge.', '2007-04-09 02:48:26.000000', NULL, 0),
(3531612, 491284, 33352, '<td valign="top">Blue Red And yellow, went to the 3 best, congratulations on the ribbon...</td>', 'Blue Red And yellow, went to the 3 best, congratulations on the ribbon...', '2007-04-09 02:50:45.000000', NULL, 0),
