(3531631, 491284, 48245, '<td valign="top">I love these kinds of sites. When I am in Japan I see these ladies going through the crowds and no one seems to notice them.<br/> <br/>Good job.</td>', 'I love these kinds of sites. When I am in Japan I see these ladies going through the crowds and no one seems to notice them. Good job.', '2007-04-09 03:14:33.000000', NULL, 0),
(3531654, 491067, 16241, '<td valign="top">oh yes! great capture, congrats</td>', 'oh yes! great capture, congrats', '2007-04-09 03:27:42.000000', NULL, 0),
(3531659, 491203, 16241, '<td valign="top">congratulations, great set up!</td>', 'congratulations, great set up!', '2007-04-09 03:29:04.000000', NULL, 0),
(3531660, 491284, 16241, '<td valign="top">cute, congrats on the ribbon.</td>', 'cute, congrats on the ribbon.', '2007-04-09 03:29:31.000000', NULL, 0),
